const fs = require('fs');
const path = require('path');
const JSZip = require('jszip');

function escapeRegExp(str) {
  return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function tagFlexible(token) {
  const escaped = escapeRegExp(token);
  let pattern = '';
  for (let i = 0; i < escaped.length; i++) {
    pattern += escaped[i];
    if (i < escaped.length - 1) pattern += '(?:<[^>]+>)*';
  }
  return pattern;
}

function xmlEscape(value) {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&apos;');
}

async function main() {
  const templatePath = '/root/offer_letter_template.docx';
  const dataPath = '/root/employee_data.json';
  const outPath = '/root/offer_letter_filled.docx';

  const employee = JSON.parse(fs.readFileSync(dataPath, 'utf8'));
  const relocationYes = String(employee.RELOCATION_PACKAGE || '').trim().toLowerCase() === 'yes';

  const data = fs.readFileSync(templatePath);
  const zip = await JSZip.loadAsync(data);
  const xmlFiles = Object.keys(zip.files).filter((f) => f.startsWith('word/') && f.endsWith('.xml'));

  const startToken = '{{IF_RELOCATION}}';
  const endToken = '{{END_IF_RELOCATION}}';
  const startRe = new RegExp(tagFlexible(startToken), 'g');
  const endRe = new RegExp(tagFlexible(endToken), 'g');
  const blockRe = new RegExp(tagFlexible(startToken) + '[\s\S]*?' + tagFlexible(endToken), 'g');

  for (const file of xmlFiles) {
    let xml = await zip.files[file].async('string');

    if (relocationYes) {
      xml = xml.replace(startRe, '').replace(endRe, '');
    } else {
      xml = xml.replace(blockRe, '');
    }

    for (const [key, rawValue] of Object.entries(employee)) {
      const token = `{{${key}}}`;
      const re = new RegExp(tagFlexible(token), 'g');
      xml = xml.replace(re, xmlEscape(rawValue));
    }

    zip.file(file, xml);
  }

  const out = await zip.generateAsync({ type: 'nodebuffer' });
  fs.writeFileSync(outPath, out);

  // Basic verification: ensure no placeholders remain.
  const outZip = await JSZip.loadAsync(out);
  const leftovers = new Set();
  for (const file of xmlFiles) {
    const xml = await outZip.files[file].async('string');
    const matches = xml.match(/\{\{[^}]+\}\}/g);
    if (matches) matches.forEach((m) => leftovers.add(m));
  }
  if (leftovers.size) {
    console.log('Leftover placeholders:', Array.from(leftovers).sort().join(', '));
  } else {
    console.log('All placeholders replaced.');
  }
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
